INSERT INTO `module_questions` (`id`, `module_id`, `question`, `options`, `answer`, `created_at`) VALUES
(152, 8, 'Sebuah perusahaan pengiriman barang menetapkan biaya tetap sebesar 10.000 rupiah ditambah 5.000 rupiah untuk setiap kilogram berat barang. Jika total biaya yang dibayar adalah 35.000 rupiah, manakah model persamaan linear yang benar untuk mencari berat barang (x) dalam kilogram?', '[\"10.000(x) + 5.000 = 35.000\",\"5.000(x) + 10.000 = 35.000\",\"15.000(x) = 35.000\",\"5.000(x) - 10.000 = 35.000\"]', 1, '2026-02-13 17:08:12'),
(2, 2, 'aghhhh', '[\"ahhh\",\"10\",\"ahhh\",\"ahhh\"]', 0, '2026-02-08 07:11:19'),
(198, 16, 'Jika nilai tertinggi dikurangi nilai terendah dalam sebuah distribusi data, hasilnya disebut sebagai:', '[\"Simpangan Baku\",\"Median\",\"Jangkauan\",\"Modus\"]', 2, '2026-02-24 08:42:04'),
(197, 4, 'Tokoh yang menyampaikan pidato tentang Pancasila pada tanggal 1 Juni 1945 adalah â€¦', '[\"Mohammad Hatta\",\"Soepomo\",\"Ir. Soekarno\",\"Sutan Sjahrir\"]', 2, '2026-02-24 08:42:01'),
